const now = new Date();
return [
  { json: { symbol: 'US10Y', name: 'US 10-Year Treasury', source: 'fred', timestamp: now.toISOString() } },
  { json: { symbol: 'US2Y', name: 'US 2-Year Treasury', source: 'fred', timestamp: now.toISOString() } },
  { json: { symbol: 'DGS10', name: '10-Year Treasury Rate', source: 'fred', timestamp: now.toISOString() } },
  { json: { symbol: 'DGS2', name: '2-Year Treasury Rate', source: 'fred', timestamp: now.toISOString() } }
];

const inst = $input.first().json;
const fredKey = process.env.FRED_API_KEY;
const url = `https://api.stlouisfed.org/fred/series/observations?series_id=${inst.symbol}&api_key=${fredKey}&file_type=json&sort_order=desc&limit=1`;
try {
  const resp = await fetch(url);
  const data = await resp.json();
  const latest = data.observations?.[0];
  return [{ json: { ...inst, value: parseFloat(latest?.value)||0, date: latest?.date } }];
} catch (e) {
  return [{ json: { ...inst, value: 0, error: e.message } }];
}

const md = $input.first().json;
const postgres = Postgres.main;
await postgres.query(`INSERT INTO market_data (symbol, name, value, source, timestamp) VALUES ($1,$2,$3,$4,$5)`, [md.symbol, md.name, md.value, md.source, md.timestamp]);
return [$input.first()];

const md = $input.first().json;
let analysis = null;
try {
  const prompt = `Analyze ${md.name} (${md.symbol}). Value: ${md.value}, Date: ${md.date}. Respond JSON: {"trend":"up|down|stable","forecast":"...","risk":"low|medium|high","factors":[...]}`;
  const resp = await fetch('https://api.openai.com/v1/chat/completions', {
    method: 'POST',
    headers: { 'Authorization': `Bearer ${process.env.OPENAI_API_KEY}`, 'Content-Type': 'application/json' },
    body: JSON.stringify({ model: 'gpt-4', messages: [{ role: 'user', content: prompt }], response_format: { type: 'json_object' } })
  });
  const r = await resp.json();
  analysis = JSON.parse(r.choices?.[0]?.message?.content || '{}');
} catch (e) {}
if (!analysis) return [];
await Postgres.main.query(`INSERT INTO ai_predictions (symbol, prediction_type, prediction, confidence, model_version, created_at) VALUES ($1,$2,$3,$4,'gpt-4',CURRENT_TIMESTAMP)`, [md.symbol, analysis.trend, JSON.stringify(analysis), analysis.risk==='low'?0.8:analysis.risk==='medium'?0.6:0.4]);
return [{ json: { channel: '#platform-weekly', severity: 'low', dedupeKey: `market_${md.symbol}_${md.date}`, text: `📈 *AI Analysis: ${md.name}*
*Trend:* ${analysis.trend}
*Risk:* ${analysis.risk}
*Value:* ${md.value}`, metadata: { flow: 'market_analysis', symbol: md.symbol } } }];

const newsKey = process.env.NEWS_API_KEY;
try {
  const resp = await fetch(`https://newsapi.org/v2/top-headlines?country=us&category=business&apiKey=${newsKey}&pageSize=20`);
  const data = await resp.json();
  return (data.articles||[]).map(a => ({ json: a }));
} catch (e) {
  return [{ json: { error: e.message } }];
}

const a = $input.first().json;
if (a.error) return [];
const kw = ['debt','treasury','bond','interest rate','fed','inflation','fiscal','sovereign'];
const txt = `${(a.title||'').toLowerCase()} ${(a.description||'').toLowerCase()}`;
if (!kw.some(k => txt.includes(k))) return [];
const postgres = Postgres.main;
const ex = await postgres.query(`SELECT id FROM news_articles WHERE url=$1`, [a.url]);
if (ex.rows.length > 0) return [];
await postgres.query(`INSERT INTO news_articles (title,description,url,source,published_at,keywords,created_at) VALUES ($1,$2,$3,$4,$5,$6,CURRENT_TIMESTAMP)`, [a.title, a.description, a.url, a.source?.name, a.publishedAt, []]);
return [{ json: { channel: '#market-news', severity: 'low', dedupeKey: `news_${Buffer.from(a.url||'').toString('base64').slice(0,40)}`, text: `📰 *Market News*
*Title:* ${a.title}
*Source:* ${a.source?.name}
*URL:* ${a.url}`, metadata: { flow: 'news_alert' } } }];

const postgres = Postgres.main;
const wl = await postgres.query(`SELECT symbol, name, target_value, alert_threshold FROM watchlist_securities WHERE is_active=true`);
const results = [];
for (const sec of wl.rows) {
  const latest = await postgres.query(`SELECT value FROM market_data WHERE symbol=$1 ORDER BY timestamp DESC LIMIT 1`, [sec.symbol]);
  const current = latest.rows[0]?.value || 0;
  const deviation = Math.abs(current - sec.target_value);
  const hit = deviation <= sec.alert_threshold;
  if (hit) {
    const severity = deviation <= sec.alert_threshold * 0.25 ? 'high' : 'medium';
    results.push({ json: { channel: '#watchlist-alerts', severity, dedupeKey: `watch_${sec.symbol}_${Math.round(current)}`, text: `🎯 *Watchlist Hit: ${sec.name}*
*Current:* ${current}
*Target:* ${sec.target_value}
*Deviation:* ${deviation.toFixed(2)}`, metadata: { flow: 'watchlist_alert', symbol: sec.symbol } } });
  }
}
return results;

const apis = [
  { name: 'FRED', url: 'https://api.stlouisfed.org/fred/series?series_id=DGS10&api_key=test&file_type=json' },
  { name: 'NewsAPI', url: 'https://newsapi.org/v2/top-headlines?country=us&apiKey=test' },
  { name: 'OpenAI', url: 'https://api.openai.com/v1/models' }
];
const postgres = Postgres.main;
const results = [];
for (const api of apis) {
  const start = Date.now();
  let healthy = false, status = 0, errMsg = null;
  try {
    const resp = await fetch(api.url, { signal: AbortSignal.timeout(10000) });
    status = resp.status; healthy = resp.ok;
  } catch (e) { errMsg = e.message; }
  const rt = Date.now() - start;
  await postgres.query(`INSERT INTO api_health_checks (service,status_code,response_time_ms,status,checked_at) VALUES ($1,$2,$3,$4,CURRENT_TIMESTAMP)`, [api.name, status, rt, healthy?'healthy':'unhealthy']);
  if (!healthy) {
    results.push({ json: { channel: '#api-alerts', severity: 'high', dedupeKey: `health_${api.name}_${Date.now()}`, text: `⚠️ *API Down: ${api.name}*
*Status:* ${status}
*Time:* ${rt}ms
*Error:* ${errMsg||'unhealthy'}`, metadata: { flow: 'api_health', service: api.name } } });
  }
}
return results;

const postgres = Postgres.main;
const weekAgo = new Date(Date.now() - 7*86400000);
const preds = await postgres.query(`SELECT COUNT(*) as total FROM ai_predictions WHERE created_at>=$1 AND actual_value IS NOT NULL`, [weekAgo.toISOString()]);
const news = await postgres.query(`SELECT COUNT(*) as total FROM news_articles WHERE created_at>=$1`, [weekAgo.toISOString()]);
const health = await postgres.query(`SELECT service, COUNT(CASE WHEN status='unhealthy' THEN 1 END) as failures FROM api_health_checks WHERE checked_at>=$1 GROUP BY service`, [weekAgo.toISOString()]);
return [{ json: { channel: '#platform-weekly', severity: 'low', dedupeKey: `weekly_${new Date().toISOString().split('T')[0]}`, text: `📊 *Weekly Report*
*Predictions:* ${preds.rows[0].total}
*News:* ${news.rows[0].total}
*Services:* ${health.rows.length}`, metadata: { flow: 'weekly_report' } } }];
